// lib/catalogue.data.js — the seed catalogue.
//
// 127 products across the six categories, with Indian retail prices.
//
// THREE THINGS TO KNOW:
//
// 1. Prices are integer PAISE (docs/adr/0003). ₹34,990.00 is 3499000.
//    An earlier seed carried US dollar figures (2499 for a MacBook Pro)
//    rendered with a ₹ sign, so the storefront advertised a ₹2,499 MacBook.
//    These are Indian MRPs.
//
// 2. Every product has THREE images and they match the product. They are not
//    photographs: they are SVG illustrations generated by lib/productArt.js
//    and served by /media/products/:shape/:colorway/:view.svg. The previous
//    seed rotated seven Unsplash URLs across sixty-six products, so a
//    headphone photo turned up on a power bank and every image was a live
//    dependency on a CDN that can rewrite or retire a photo ID. Generated art
//    cannot 404, weighs ~2 KB, and is correct per product by construction.
//
// 3. When you have real product photography, `IMAGE_OVERRIDES` below is the
//    one place to put it. Keyed by exact product title; an entry wins over
//    the generated art. Nothing else changes.
//
// The image paths are RELATIVE (`/media/products/...`). The frontend resolves
// them against the API origin via src/lib/images.js, so the same seed works on
// localhost and in production without a rebuild.

import { artPath, SHAPES, COLORWAYS } from './productArt.js';
import { REAL_IMAGES_BY_SHAPE, REAL_IMAGES_BY_TITLE } from './realImages.data.js';

/**
 * Real photography overrides. Keyed by product title; falls back to real
 * high-res photography by shape, and finally generated art.
 */
export const IMAGE_OVERRIDES = {
  ...REAL_IMAGES_BY_TITLE,
};

/** front / angle / detail of one shape in one colourway. */
const views = (shape, colorway) => [
  artPath(shape, colorway, 'front'),
  artPath(shape, colorway, 'angle'),
  artPath(shape, colorway, 'detail'),
];

/**
 * Compact product definition.
 * price/mrp in rupees for readability here — converted to paise on the way out.
 * `shape` and `colorway` must exist in lib/productArt.js; the assertion at the
 * bottom of this file fails the boot rather than serving a broken image.
 */
const define = (title, brand, category, price, mrp, stock, featured, specs, description, shape, colorway) => ({
  title, brand, category, price, mrp, stock, featured, specs, description, shape, colorway,
});

