// Every row's artwork must exist, or the store ships a broken image. Fail at
// import time instead — a boot that refuses is cheaper to debug than a 404 a
// customer finds.
for (const item of RAW) {
  if (!SHAPES[item.shape]) {
    throw new Error(`catalogue.data.js: "${item.title}" uses unknown art shape "${item.shape}"`);
  }
  if (!COLORWAYS[item.colorway]) {
    throw new Error(`catalogue.data.js: "${item.title}" uses unknown colourway "${item.colorway}"`);
  }
  if (item.price > item.mrp) {
    throw new Error(`catalogue.data.js: "${item.title}" costs more than its MRP`);
  }
}

/** Rupees → paise, and shape each row into a Product document. */
export const CATALOGUE = RAW.map((item) => ({
  title: item.title,
  description: item.description,
  price: Math.round(item.price * 100),
  originalPrice: Math.round(item.mrp * 100),
  category: item.category,
  brand: item.brand,
  stock: item.stock,
  // A plausible spread rather than 4.5 on everything — a catalogue where every
  // rating is identical makes the "top rated" sort meaningless.
  rating: Number((3.9 + ((item.title.length * 7) % 11) / 10).toFixed(1)),
  numReviews: 8 + ((item.title.length * 13) % 240),
  images:
    IMAGE_OVERRIDES[item.title] ??
    REAL_IMAGES_BY_SHAPE[item.shape] ??
    views(item.shape, item.colorway),
  specifications: item.specs,
  featured: item.featured,
}));

export const CATALOGUE_STATS = {
  total: CATALOGUE.length,
  categories: [...new Set(CATALOGUE.map((p) => p.category))].length,
  brands: [...new Set(CATALOGUE.map((p) => p.brand))].length,
  featured: CATALOGUE.filter((p) => p.featured).length,
  outOfStock: CATALOGUE.filter((p) => p.stock === 0).length,
  lowStock: CATALOGUE.filter((p) => p.stock > 0 && p.stock <= 5).length,
  shapes: [...new Set(RAW.map((p) => p.shape))].length,
  overrides: Object.keys(IMAGE_OVERRIDES).length,
};
